#include "scenario_tools.hpp"
#include <QCoreApplication>
#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonArray>
#include <cmath>
#include <iostream>
using scenario::Value;
Value from(const QJsonValue& j){if(j.isNull()||j.isUndefined())return {};if(j.isBool())return j.toBool();if(j.isDouble())return j.toDouble();if(j.isString())return j.toString().toStdString();if(j.isArray()){Value::Array a;for(auto v:j.toArray())a.push_back(from(v));return a;}Value::Object o;auto jo=j.toObject();for(auto it=jo.begin();it!=jo.end();++it)o[it.key().toStdString()]=from(it.value());return o;}
int checks=0;
void compare(const Value& actual,const QJsonValue& expected,const std::string& path){++checks;if(expected.isObject()){auto p=std::get_if<Value::Object>(&actual.data);if(!p)throw std::runtime_error(path+" not object");auto e=expected.toObject();for(auto it=e.begin();it!=e.end();++it){auto at=p->find(it.key().toStdString());if(at==p->end())throw std::runtime_error(path+" missing "+it.key().toStdString());compare(at->second,it.value(),path+"."+it.key().toStdString());}}else if(expected.isArray()){auto p=std::get_if<Value::Array>(&actual.data);auto e=expected.toArray();if(!p||p->size()!=std::size_t(e.size()))throw std::runtime_error(path+" array length");for(int i=0;i<e.size();++i)compare((*p)[i],e[i],path+"["+std::to_string(i)+"]");}else if(expected.isDouble()){auto p=std::get_if<double>(&actual.data);double e=expected.toDouble();if(!p||!std::isfinite(*p)||std::abs(*p-e)>std::max(1e-6,std::abs(e)*1e-10))throw std::runtime_error(path+" number got "+(p?std::to_string(*p):"not-number")+" expected "+std::to_string(e));}else if(expected.isNull()){if(!std::holds_alternative<std::nullptr_t>(actual.data))throw std::runtime_error(path+" not null");}else if(expected.isBool()){auto p=std::get_if<bool>(&actual.data);if(!p||*p!=expected.toBool())throw std::runtime_error(path+" boolean");}else{auto p=std::get_if<std::string>(&actual.data);if(!p||*p!=expected.toString().toStdString())throw std::runtime_error(path+" string");}}
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc<2)return 2;QFile f(argv[1]);if(!f.open(QIODevice::ReadOnly))return 2;auto cases=QJsonDocument::fromJson(f.readAll()).object().value("cases").toArray();int fail=0,done=0;for(auto v:cases){auto c=v.toObject();std::string m=c["module"].toString().toStdString();if(argc>2&&m!=argv[2])continue;try{auto got=scenario::evaluate(m,from(c["input"]));auto& o=std::get<Value::Object>(got.data);compare(o.at("result"),c["expected"],c["name"].toString().toStdString());++done;}catch(const std::exception& e){++fail;std::cerr<<c["name"].toString().toStdString()<<": "<<e.what()<<'\n';}}std::cout<<"scenario legacy: "<<done<<" cases, "<<checks<<" assertions, "<<fail<<" failed\n";return fail?1:0;}
